Action: run_sql({'query': '\nWITH ranked AS (\n  SELECT slchd_establishment_key, inspection_score,\n         row_number() OVER (PARTITION BY slchd_establishment_key ORDER BY inspection_date DESC) rn\n  FROM inspections WHERE inspection_score IS NOT NULL\n)\nSELECT inspection_score FROM ranked WHERE rn=1\n'})

Action: run_sql({'query': "\nSELECT date_part('year', inspection_date) AS yr, avg(inspection_score) AS avg_score, count(*) AS n\nFROM inspections WHERE inspection_score IS NOT NULL\nGROUP BY yr ORDER BY yr\n"})

Action: run_sql({'query': '\nSELECT it.description, avg(i.inspection_score) AS avg_score, count(*) AS n\nFROM inspections i JOIN inspection_types it ON i.inspection_type_id = it.inspection_type_id\nWHERE i.inspection_score IS NOT NULL\nGROUP BY it.description ORDER BY n DESC\n'})

Action: run_sql({'query': "\nSELECT CASE WHEN inspection_score = 0 THEN '0 (clean)'\n            WHEN inspection_score BETWEEN 1 AND 5 THEN '1-5'\n            WHEN inspection_score BETWEEN 6 AND 10 THEN '6-10'\n            WHEN inspection_score BETWEEN 11 AND 20 THEN '11-20'\n            WHEN inspection_score BETWEEN 21 AND 40 THEN '21-40'\n            ELSE '41+' END AS score_bucket,\n       count(*) AS n\nFROM inspections WHERE inspection_score IS NOT NULL\nGROUP BY score_bucket\n"})

