Action: plot_chart({'query': 'SELECT inspection_score FROM inspections WHERE inspection_score IS NOT NULL', 'chart_type': 'histogram', 'x': 'inspection_score', 'title': 'Distribution of Inspection Scores Across All 7,798 Inspections (0=clean, higher=worse)'})

Action: plot_chart({'query': "\nSELECT CASE WHEN inspection_score = 0 THEN '1: 0 (clean)'\n            WHEN inspection_score BETWEEN 1 AND 5 THEN '2: 1-5'\n            WHEN inspection_score BETWEEN 6 AND 10 THEN '3: 6-10'\n            WHEN inspection_score BETWEEN 11 AND 20 THEN '4: 11-20'\n            WHEN inspection_score BETWEEN 21 AND 40 THEN '5: 21-40'\n            ELSE '6: 41+' END AS score_bucket,\n       count(*) AS n\nFROM inspections WHERE inspection_score IS NOT NULL\nGROUP BY score_bucket ORDER BY score_bucket\n", 'chart_type': 'bar', 'x': 'score_bucket', 'y': 'n', 'title': 'Inspection Count by Score Severity Bucket'})

Action: plot_chart({'query': "\nSELECT date_part('year', inspection_date) AS yr, avg(inspection_score) AS avg_score\nFROM inspections WHERE inspection_score IS NOT NULL\nGROUP BY yr ORDER BY yr\n", 'chart_type': 'line', 'x': 'yr', 'y': 'avg_score', 'title': 'Average Inspection Score by Year (2009-2026)'})

Action: plot_chart({'query': '\nSELECT it.description AS inspection_type, avg(i.inspection_score) AS avg_score, count(*) AS n\nFROM inspections i JOIN inspection_types it ON i.inspection_type_id = it.inspection_type_id\nWHERE i.inspection_score IS NOT NULL\nGROUP BY it.description ORDER BY n DESC\n', 'chart_type': 'bar', 'x': 'inspection_type', 'y': 'avg_score', 'title': 'Average Inspection Score by Inspection Type'})

Action: plot_chart({'query': '\nWITH ranked AS (\n  SELECT ek.name, ek.slchd_establishment_key, i.inspection_score,\n         row_number() OVER (PARTITION BY i.slchd_establishment_key ORDER BY i.inspection_date DESC) rn\n  FROM inspections i JOIN establishment_keys ek ON i.slchd_establishment_key = ek.slchd_establishment_key\n  WHERE i.inspection_score IS NOT NULL\n)\nSELECT name, inspection_score AS most_recent_score\nFROM ranked WHERE rn=1\nORDER BY inspection_score DESC LIMIT 15\n', 'chart_type': 'bar', 'x': 'name', 'y': 'most_recent_score', 'title': 'Top 15 Establishments by Most Recent (Worst) Inspection Score'})

Action: plot_chart({'query': '\nSELECT ek.name, count(*) AS critical_violations\nFROM violations v\nJOIN violation_codes vc ON v.violation_code_id = vc.violation_code_id\nJOIN inspections i ON v.inspection_id = i.inspection_id\nJOIN establishment_keys ek ON i.slchd_establishment_key = ek.slchd_establishment_key\nWHERE vc.critical = true\nGROUP BY ek.name\nORDER BY critical_violations DESC LIMIT 15\n', 'chart_type': 'bar', 'x': 'name', 'y': 'critical_violations', 'title': 'Top 15 Establishments by Total Critical Violations (All-Time)'})

